from pathlib import Path
import base64
import shutil
import time

PROJECT = Path(r"C:\Users\Shadow\Desktop\app\AudioVidoLivingCity")
AGENT = Path(r"C:\Users\Shadow\Desktop\Unreal-Agent")
PLUGIN = PROJECT / "Plugins" / "UnrealAgentBridge" / "Source" / "UnrealAgentBridge"

H = PLUGIN / "Public" / "UnrealAgentBlueprintLibrary.h"
CPP = PLUGIN / "Private" / "UnrealAgentBlueprintLibrary.cpp"
BRIDGE = AGENT / "tools" / "unreal" / "unreal_bridge.py"
API = AGENT / "app" / "api.py"

for p in (H, CPP, BRIDGE, API):
    if not p.exists():
        raise RuntimeError("Required file missing: " + str(p))

stamp = time.strftime("%Y%m%d_%H%M%S")
backup = AGENT / "backups" / ("native_visual_v5_1_" + stamp)
backup.mkdir(parents=True, exist_ok=True)

for p in (H, CPP, BRIDGE, API):
    name = str(p).replace(":", "").replace("\\", "__").replace("/", "__")
    shutil.copy2(p, backup / name)

h = H.read_text(encoding="utf-8-sig")
cpp = CPP.read_text(encoding="utf-8-sig")
bridge = BRIDGE.read_text(encoding="utf-8-sig")
api = API.read_text(encoding="utf-8-sig")

header_decl = base64.b64decode("ICAgIFVGVU5DVElPTihCbHVlcHJpbnRDYWxsYWJsZSwgQ2F0ZWdvcnk9IlVucmVhbCBBZ2VudHxWaWV3cG9ydCIpCiAgICBzdGF0aWMgRlN0cmluZyBDYXB0dXJlQWN0aXZlVmlld3BvcnREZXRhaWxlZCgKICAgICAgICBjb25zdCBGU3RyaW5nJiBPdXRwdXRQYXRoCiAgICApOw==").decode("utf-8")
cpp_impl = base64.b64decode("").decode("utf-8")
bridge_method = base64.b64decode("").decode("utf-8")

if "CaptureActiveViewportDetailed" not in h:
    pos = h.rfind("};")
    if pos < 0:
        raise RuntimeError("Could not find header class closing brace.")
    h = h[:pos].rstrip() + "\n\n" + header_decl + "\n" + h[pos:]

if '#include "LevelEditorViewport.h"' not in cpp:
    anchor = '#include "Editor.h"'
    if anchor in cpp:
        cpp = cpp.replace(
            anchor,
            anchor + '\n#include "LevelEditorViewport.h"',
            1
        )
    else:
        first = '#include "UnrealAgentBlueprintLibrary.h"'
        if first not in cpp:
            raise RuntimeError("Could not find CPP include insertion point.")
        cpp = cpp.replace(
            first,
            first + '\n#include "Editor.h"\n#include "LevelEditorViewport.h"',
            1
        )

start_marker = "bool UUnrealAgentBlueprintLibrary::CaptureActiveViewport("
start = cpp.find(start_marker)

if start < 0:
    raise RuntimeError("Existing CaptureActiveViewport implementation not found.")

cpp = cpp[:start].rstrip() + "\n\n" + cpp_impl + "\n"

start_marker = "    def capture_unreal_viewport(self):"
end_marker = "    def visual_review_unreal(self):"
start = bridge.find(start_marker)
end = bridge.find(end_marker, start)

if start < 0 or end < 0:
    raise RuntimeError("Could not locate bridge capture method.")

bridge = bridge[:start] + bridge_method + "\n\n" + bridge[end:]

api = api.replace('version="5.0.0"', 'version="5.1.0"', 1)
api = api.replace('"version": "Adaptive API v5"', '"version": "Adaptive API v5.1"', 1)

compile(bridge, str(BRIDGE), "exec")
compile(api, str(API), "exec")

H.write_text(h, encoding="utf-8")
CPP.write_text(cpp, encoding="utf-8")
BRIDGE.write_text(bridge, encoding="utf-8")
API.write_text(api, encoding="utf-8")

print("PATCH_V5_1_SOURCE=PASS")
print("BACKUP_DIR=" + str(backup))
